// baseValue returns the value in joules.
func (e Energy) baseValue() float64 {
	return e.value * e.unit.Factor()
}

// Add returns the sum of the energies, expressed in the receiver's unit.
func (e Energy) Add(other Energy) Energy {
	return Energy{value: e.value + other.value*energy.Rate(other.unit, e.unit), unit: e.unit}
}

// Sub returns the difference of the energies, expressed in the receiver's unit.
func (e Energy) Sub(other Energy) Energy {
	return Energy{value: e.value - other.value*energy.Rate(other.unit, e.unit), unit: e.unit}
}

